import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { QGridRowContentVariant } from '../types/grid-row-content-variant.type';

const MIN_VALUE = 1;
const MAX_VALUES = {
  xxs: 4,
  xs: 8,
  sm: 8,
  md: 12,
  lg: 12,
  xl: 12,
};

@Component({
  selector: 'q-grid-row',
  template: `<ng-content />`,
  styleUrls: ['./grid-row.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QGridRowComponent {
  @Input() contentType: QGridRowContentVariant = 'primary';
  @Input({ transform: booleanAttribute }) extraSpacingRight = false;
  @Input({ transform: booleanAttribute }) extraSpacingLeft = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-grid-row';

  @Input() get xxs(): number {
    return this._xxs;
  }
  set xxs(value: number) {
    if (value > MAX_VALUES.xxs) {
      this._xxs = MAX_VALUES.xxs;
    } else if (value < MIN_VALUE) {
      this._xxs = MIN_VALUE;
    } else {
      this._xxs = value;
    }
  }

  @Input() get xs(): number {
    return this._xs;
  }
  set xs(value: number) {
    if (value > MAX_VALUES.xs) {
      this._xs = MAX_VALUES.xs;
    } else if (value < MIN_VALUE) {
      this._xs = MIN_VALUE;
    } else {
      this._xs = value;
    }
  }

  @Input() get sm(): number {
    return this._sm;
  }
  set sm(value: number) {
    if (value > MAX_VALUES.sm) {
      this._sm = MAX_VALUES.sm;
    } else if (value < MIN_VALUE) {
      this._sm = MIN_VALUE;
    } else {
      this._sm = value;
    }
  }

  @Input() get md(): number {
    return this._md;
  }
  set md(value: number) {
    if (value > MAX_VALUES.md) {
      this._md = MAX_VALUES.md;
    } else if (value < MIN_VALUE) {
      this._md = MIN_VALUE;
    } else {
      this._md = value;
    }
  }

  @Input() get lg(): number {
    return this._lg;
  }
  set lg(value: number) {
    if (value > MAX_VALUES.lg) {
      this._lg = MAX_VALUES.lg;
    } else if (value < MIN_VALUE) {
      this._lg = MIN_VALUE;
    } else {
      this._lg = value;
    }
  }

  @Input() get xl(): number {
    return this._xl;
  }
  set xl(value: number) {
    if (value > MAX_VALUES.xl) {
      this._xl = MAX_VALUES.xl;
    } else if (value < MIN_VALUE) {
      this._xl = MIN_VALUE;
    } else {
      this._xl = value;
    }
  }

  @HostBinding('class') get hostClasses(): string {
    return this._classNames();
  }

  private _xxs = MAX_VALUES.xxs;
  private _xs = 0;
  private _sm = 0;
  private _md = 0;
  private _lg = 0;
  private _xl = 0;

  _addExtraPaddingRight(): void {
    this.extraSpacingRight = true;
  }

  _addExtraPaddingLeft(): void {
    this.extraSpacingLeft = true;
  }

  _classNames(): string {
    return `
      q-grid-row
      ${this.getSizeClass('xxs')}
      ${this.getSizeClass('xs')}
      ${this.getSizeClass('sm')}
      ${this.getSizeClass('md')}
      ${this.getSizeClass('lg')}
      ${this.getSizeClass('xl')}
      ${this.contentType}
      ${this.extraSpacingRight ? 'x-spacing-r' : ''}
      ${this.extraSpacingLeft ? 'x-spacing-l' : ''}
    `;
  }

  private getSizeClass(size: string): string {
    const thisSizeClass = this[size as keyof QGridRowComponent];
    if (thisSizeClass) {
      return `${size}-${thisSizeClass}`;
    }
    return '';
  }
}
